    public static class AdamAsnyk
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Ale nie depczcie przeszłości ołtarzy, Choć macie sami doskonalsze wznieść: Na nich się jeszcze święty ogień żarzy, I miłość ludzka stoi tam na straży, I wy winniście im cześć!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Ból zasnął we mnie już zcicha, Jak dziecię krzykiem zmęczone; Łzy na dno duszy kielicha Spływają niepostrzeżone.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Dla serc szlachetnych najwyższą rozkoszą, gdy drugim radość w niedoli przynoszą.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Jednego serca! tak mało mi trzeba, A jednak widzę, że żądam – za wiele!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Każda epoka ma swe własne cele I zapomina o wczorajszych snach: Nieście więc wiedzy pochodnię na czele I nowy udział bierzcie w wieków dziele – Przyszłości podnoście gmach!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Lecz się powracać myślą strzeż Do niższej sfery bytu, Ocknie się bowiem w tobie zwierz… I spadniesz z marzeń szczytu!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Miejmy nadzieję!… nie tę lichą, marną, Co rdzeń spróchniały w wątły kwiat ubiera, Lecz tę niezłomną, która tkwi jak ziarno Przyszłych poświęceń w duszy bohatera.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Między nami nic nie było! Żadnych zwierzeń, wyznań żadnych! Nic nas z sobą nie łączyło — Prócz wiosennych marzeń zdradnych…", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Miłości! tyś zawsze wielką; Wielką w twoich zwątpieniach, wielką w twojej wierze, Jeszcze większą w żądaniach, największą w ofierze.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Na własne mroki najlepszą pociechą zapalić światło pod ubogich strzechą.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Nie baw się w bohatera! Nadludzką nie błyszcz cnotą: Kto w górę wciąż spoziera, Ten łatwo wejdzie w błoto.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Nie pomogą próżne żale… Ból swój niebu trza polecić — A samemu wciąż wytrwale Trzeba naprzód iść… i świecić!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Nie rozumiemy z ludzi nikogo I właśnie dla tej przyczyny, Swych bliźnich zawsze sądzimy wrogo Myśli, uczucia i czyny.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Przestańmy własną pieścić się boleścią, Przestańmy ciągłym lamentem się poić: Kochać się w skargach jest rzeczą niewieścią, Mężom przystoi w milczeniu się zbroić…", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Szczęśliwe kwiaty! mogą patrzeć śmiele I składać życzeń utajonych wiele, I śnić o szczęściu jeden dzień słoneczny… Zanim z tęsknoty uwiędną serdecznej.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Szukajcie prawdy jasnego płomienia, Szukajcie nowych, nieodkrytych dróg!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Tacy poeci, jaka jest publiczność!", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Tam, gdzie w sercach bezmyślność i bierność, Krzewić się może jedna tylko mierność.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Ten jest prawdziwie samotnym na ziemi, Kto nawet współczuć nie umie z drugiemi.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Ten ma największe hojności porywy, Komu fortuna odmówiła mienia; A ten najbardziej bywa gadatliwy, Co nie ma właśnie nic do powiedzenia.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Wszystkie żywota gorycze Zamknąłem w sercu, jak w grobie: Niech drzemią w nim tajemnicze, Nie mówiąc światu o sobie.", Author = "Adam Asnyk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Adam_Asnyk", Text = "Żyć to nie znaczy iść przez róże, Sięgać po laury, zbierać oklaski. Żyć to znaczy przetrwać wszystkie burze I dążyć tam, gdzie świecą ideałów blaski.", Author = "Adam Asnyk" },
        };
    }
